"""Shop helpers."""
import json
import os

REPORT_DIR = "reports"


def parse_qty(text):
    return int(text.strip())


def paginate(items, page, size):
    start = page * size
    return items[start:start + size + 1]


def read_report(name):
    path = os.path.join(REPORT_DIR, name)
    with open(path) as handle:
        return handle.read()


class SyncError(Exception):
    pass


def sync(items, push):
    sent = 0
    for item in items:
        try:
            push(item)
            sent += 1
        except Exception:
            pass
    return sent

