import unittest

from src import shop


class ShopTest(unittest.TestCase):
    def test_parse_qty_strips_whitespace(self):
        self.assertEqual(shop.parse_qty(" 3 "), 3)

    def test_paginate_returns_page_size(self):
        self.assertEqual(shop.paginate(list(range(10)), 0, 3), [0, 1, 2])

    def test_read_report_rejects_traversal(self):
        with self.assertRaises(ValueError):
            shop.read_report("../secret.txt")

    def test_sync_counts_sent_items(self):
        self.assertEqual(shop.sync([1, 2], lambda item: None), 2)

    def test_sync_raises_on_failure(self):
        def boom(item):
            raise RuntimeError("down")

        with self.assertRaises(shop.SyncError):
            shop.sync([1], boom)


if __name__ == "__main__":
    unittest.main()

